"""Generate the Brief A workflow (slot w2-rA)."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
BLOCK_URL = "https://blocked.invalid/not-sent"

HEAD = ("After every tool result, speak to the customer or call the next tool. Never end a turn with nothing. "
        "Call one tool per message. When a tool result contains what_to_do_next, follow it. "
        "Before calling close_call, thank the customer and say goodbye in that same message; close_call is always the last tool call.\n\n")


def api_tool(name, desc, body_props, required, pre=None, post=None, mapping=None, retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": f"{BASE}/{name}"},
                "method": {"type": "string", "default": "POST"},
                "connect_retries": {"type": "number", "default": 0},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "properties": props, "required": required},
            }},
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


# ---------------------------------------------------------------- hooks
POST_COMMON = """
def _V():
    try:
        v = vars
        if isinstance(v, dict):
            return v
    except Exception:
        pass
    return {}
def _data(result):
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if not isinstance(d, dict):
            d = {'ok': False, 'error': str(result.get('message') or 'no response')}
            result['data'] = d
        return d
    return {}
def _isok(d):
    return str(d.get('ok')).lower() == 'true'
"""

VERIFY_PRE = r"""
try:
    import re
    b = config.get('body')
    if isinstance(b, dict):
        f = str(b.get('field') or '')
        a = str(b.get('answer') or '').strip()
        if f == 'phone_last4':
            digits = re.sub(r'[^0-9]', '', a)
            if len(digits) >= 4:
                b['answer'] = digits[-4:]
        elif f == 'date_of_birth':
            m = re.match(r'^\s*(\d{1,2})[./\- ](\d{1,2})[./\- ](\d{4})\s*$', a)
            if m:
                b['answer'] = '%s-%02d-%02d' % (m.group(3), int(m.group(2)), int(m.group(1)))
            else:
                m = re.match(r'^\s*(\d{4})[./\- ](\d{1,2})[./\- ](\d{1,2})\s*$', a)
                if m:
                    b['answer'] = '%s-%02d-%02d' % (m.group(1), int(m.group(2)), int(m.group(3)))
except Exception:
    pass
"""

VERIFY_POST = POST_COMMON + r"""
try:
    d = _data(result)
    if d.get('hint') == 'day_month_swapped':
        d['what_to_do_next'] = 'Not counted as a wrong answer: the day and month seem swapped. Ask the customer to say their date of birth again with the month as a word (for example 3 April 1985). Then call verify_identity again.'
    elif str(d.get('all_verified')).lower() == 'true':
        d['what_to_do_next'] = 'Both security questions passed.'
    elif str(d.get('verified')).lower() == 'true':
        d['what_to_do_next'] = 'This answer is correct. Now ask the remaining security question (after the date of birth: the last four digits of the phone number on file). Do not mention any account information.'
    elif str(d.get('wrong_answers_left')) in ('0', '0.0'):
        d['what_to_do_next'] = 'The security check has FAILED (three wrong answers). Do not mention any account, debt or payment. Tell the customer to use the Freya Bank mobile app or visit a branch, thank them and say goodbye, and in the same message call close_call with outcome not_verified and reason failed.'
    elif not _isok(d) and d.get('wrong_answers_left') is None:
        d['what_to_do_next'] = 'The answer could not be read (this does not count as a wrong answer). Ask the customer to repeat it. A date of birth must be sent as YYYY-MM-DD; a date in numbers only is day, then month, then year.'
    else:
        d['what_to_do_next'] = 'That answer is not correct. Wrong answers left: ' + str(d.get('wrong_answers_left')) + '. Say it did not match and ask the same security question again. Do not reveal the right answer.'
except Exception:
    pass
"""

CALLBACK_PRE = r"""
try:
    import re
    b = config.get('body')
    ok = True
    if isinstance(b, dict):
        dte = str(b.get('date') or '').strip()[:10]
        t = str(b.get('time') or '').strip().lower()
        m = re.match(r'^(\d{1,2})(?:[:.h](\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?$', t)
        hm = None
        if m:
            h = int(m.group(1)); mi = int(m.group(2) or 0); ap = (m.group(3) or '').replace('.', '')
            if ap == 'pm' and h < 12:
                h += 12
            if ap == 'am' and h == 12:
                h = 0
            hm = '%02d:%02d' % (h, mi)
            b['time'] = hm
        today = str(vars.get('today_iso') or '')
        nxt = str(vars.get('next_business_day_iso') or '')
        nowhm = str(vars.get('now_hm') or '00:00')
        if today and nxt:
            if hm is None or hm < '10:00' or hm > '19:00':
                ok = False
            elif dte == today:
                ok = hm > nowhm
            elif dte == nxt:
                ok = True
            else:
                ok = False
    if not ok:
        config['url'] = '""" + BLOCK_URL + r"""'
        vars['callback_guard'] = 'blocked'
    else:
        vars['callback_guard'] = 'passed'
except Exception:
    pass
"""

CALLBACK_POST = POST_COMMON + r"""
try:
    V = _V()
    d = _data(result)
    if _isok(d):
        d['what_to_do_next'] = 'The callback is booked. Tell the person the customer will be called back at that time (give no reason for the call), thank them, say goodbye, and in the same message call close_call with outcome not_reached and reason callback.'
    else:
        n = 0
        try:
            n = int(V.get('callback_rejections') or 0)
        except Exception:
            n = 0
        n += 1
        V['callback_rejections'] = n
        d['ok'] = False
        if n >= 2:
            d['what_to_do_next'] = 'NOT booked: the time is outside the allowed callback window again. Do not book anything. Thank the person, say goodbye, and in the same message call close_call with outcome not_reached and reason no_callback.'
        else:
            d['what_to_do_next'] = 'NOT booked: callbacks are only possible today later than now, or on the next business day, between 10:00 and 19:00. Ask the person once for another time inside that window.'
except Exception:
    pass
"""

PROMISE_PRE = r"""
try:
    b = config.get('body')
    reason = ''
    if isinstance(b, dict):
        if str(vars.get('promise_recorded') or '') == 'yes':
            reason = 'a promise is already recorded for this product; it cannot be changed or cancelled in this call (the customer can change it in the mobile app)'
        dte = str(b.get('date') or '').strip()[:10]
        b['date'] = dte
        allowed = [x for x in str(vars.get('allowed_promise_dates') or '').split(',') if x]
        if not reason and allowed and dte not in allowed:
            reason = 'the date ' + dte + ' is not allowed (it must be a business day from today up to the deadline ' + str(vars.get('deadline_iso') or '') + ')'
        try:
            amt = float(str(b.get('amount')).replace(',', ''))
            b['amount'] = round(amt, 2)
            fl = vars.get('floor_value')
            pd = vars.get('past_due_value')
            if not reason and fl not in (None, '') and pd not in (None, ''):
                if amt < float(fl) - 0.001:
                    reason = 'the amount is below the minimum that can be recorded (' + str(vars.get('floor_text') or '') + ')'
                elif amt > float(pd) + 0.001:
                    reason = 'the amount is more than the past-due amount (' + str(vars.get('past_due_text') or '') + ')'
        except Exception:
            if not reason:
                reason = 'the amount is not a number'
        pid = vars.get('product_id')
        if pid:
            b['product_id'] = str(pid)
    if reason:
        config['url'] = '""" + BLOCK_URL + r"""'
        vars['promise_guard'] = 'blocked'
        vars['promise_guard_reason'] = reason
    else:
        vars['promise_guard'] = 'passed'
        vars['promise_guard_reason'] = ''
except Exception:
    pass
"""

PROMISE_POST = POST_COMMON + r"""
try:
    V = _V()
    d = _data(result)
    if _isok(d):
        V['promise_recorded'] = 'yes'
        d['what_to_do_next'] = 'The promise IS recorded. Tell the customer it is recorded and say exactly: "You will receive a text message confirming this promise." Then ask if there is anything else; when done, thank them, say goodbye, and in the same message call close_call with outcome promise (no reason).'
    elif str(V.get('promise_guard') or '') == 'blocked':
        d['ok'] = False
        d['what_to_do_next'] = 'NOT recorded and not sent, because ' + str(V.get('promise_guard_reason') or 'the date or amount breaks the rules') + '. Do not say it is recorded. Explain this briefly and offer a value allowed by the rules in your facts, read it back and ask "Do you confirm?" again.'
    else:
        n = 0
        try:
            n = int(V.get('promise_service_failures') or 0)
        except Exception:
            n = 0
        n += 1
        V['promise_service_failures'] = n
        d['ok'] = False
        if n >= 2:
            d['what_to_do_next'] = 'Recording FAILED again. Tell the customer you could not record the promise. Thank them, say goodbye, and in the same message call close_call with outcome no_promise and reason service_error.'
        else:
            d['what_to_do_next'] = 'Recording FAILED, the promise is NOT recorded. Do not say it is recorded. Call create_promise once more right now with the same product, amount and date.'
except Exception:
    pass
"""

TRANSFER_POST = POST_COMMON + r"""
try:
    d = _data(result)
    if _isok(d):
        d['what_to_do_next'] = 'The transfer is arranged. Tell the customer they will be connected, thank them, say goodbye, and in the same message call close_call with outcome transferred and the reason for this queue: support -> support, restructuring -> restructuring, general -> human.'
    else:
        d['what_to_do_next'] = 'The transfer FAILED. Tell the customer you could not connect them right now. Do not say they are being transferred.'
except Exception:
    pass
"""

CLOSE_PRE = r"""
try:
    b = config.get('body')
    if isinstance(b, dict):
        if b.get('outcome') in ('promise', 'paid') or not str(b.get('reason') or '').strip():
            b.pop('reason', None)
except Exception:
    pass
"""

CLOSE_POST = POST_COMMON + r"""
try:
    d = _data(result)
    if _isok(d):
        d['what_to_do_next'] = 'The call is closed. Say nothing more.'
    else:
        d['what_to_do_next'] = 'close_call failed: check the outcome and reason pair against the outcome table and call close_call again.'
except Exception:
    pass
"""

# ---------------------------------------------------------------- tools
OUTCOME_TABLE = ("Allowed pairs: promise (no reason) = at least one promise recorded; paid (no reason) = customer already paid this past-due amount; "
                 "transferred + restructuring | human | support; no_promise + refused | hardship | dispute | service_error; "
                 "not_verified + failed | declined; not_reached + callback | no_callback | wrong_number | deceased | unclear. "
                 "If a transfer follows a recorded promise, use transferred with that transfer's reason.")


def close_tool():
    return api_tool(
        "close_call",
        "End the call record. CALL it exactly once, as the very last tool call, in the same message as your thank-you and goodbye. " + OUTCOME_TABLE,
        {
            "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"],
                        "default": "{{outcome}}", "description": "How the call ended. One of: promise, paid, transferred, no_promise, not_verified, not_reached."},
            "reason": {"type": "string",
                       "enum": ["restructuring", "human", "support", "refused", "hardship", "dispute", "service_error", "failed", "declined",
                                "callback", "no_callback", "wrong_number", "deceased", "unclear"],
                       "default": "{{reason}}", "description": "Reason for the outcome. Leave out for promise and paid. " + OUTCOME_TABLE},
        },
        ["outcome"], pre=CLOSE_PRE, post=CLOSE_POST)


def callback_tool():
    return api_tool(
        "schedule_callback",
        "Book a callback for the customer when someone else answered. CALL it as soon as the person gives a day and time inside the allowed window.",
        {
            "date": {"type": "string", "default": "{{date}}", "description": "Callback date as YYYY-MM-DD: today or the next business day only."},
            "time": {"type": "string", "default": "{{time}}", "description": "Callback time as HH:MM, 24 hour, from 10:00 to 19:00."},
        },
        ["date", "time"], pre=CALLBACK_PRE, post=CALLBACK_POST)


def transfer_tool():
    return api_tool(
        "transfer_to_agent",
        "Hand the customer to a person. CALL it with queue support when the customer accepted the offer to connect with the customer support team (hardship); "
        "queue restructuring when the customer asks for a new payment plan or lower instalments; queue general when the customer still insists on a human after you asked once whether you can help.",
        {"queue": {"type": "string", "enum": ["restructuring", "general", "support"], "default": "{{queue}}",
                   "description": "One of: support (hardship offer accepted), restructuring (new plan / lower instalments), general (insists on a human)."}},
        ["queue"], post=TRANSFER_POST)


def verify_tool():
    return api_tool(
        "verify_identity",
        "Check ONE security answer. CALL it every time the customer answers a security question, once per answer.",
        {
            "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "default": "{{field}}",
