"""Generate the Brief A workflow (slot w2-rA)."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
BLOCK_URL = "https://blocked.invalid/not-sent"

HEAD = ("After every tool result, speak to the customer or call the next tool. Never end a turn with nothing. "
        "Call one tool per message. When a tool result contains what_to_do_next, follow it. "
        "Before calling close_call, thank the customer and say goodbye in that same message; close_call is always the last tool call.\n\n")


def api_tool(name, desc, body_props, required, pre=None, post=None, mapping=None, retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": f"{BASE}/{name}"},
                "method": {"type": "string", "default": "POST"},
                "connect_retries": {"type": "number", "default": 0},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "properties": props, "required": required},
            }},
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


# ---------------------------------------------------------------- hooks
POST_COMMON = """
def _V():
    try:
        v = vars
        if isinstance(v, dict):
            return v
    except Exception:
        pass
    return {}
def _data(result):
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
